def parse_records(records):
    result = []
    for entry in records:
        parts = entry.split(',')
        if len(parts) != 2:
            continue
        name = parts[0].strip()
        score_str = parts[1].strip()
        try:
            score = int(score_str)
        except ValueError:
            continue
        result.append((name, score))
    return result

